cssScope:
.cg-card{background:linear-gradient(135deg,#fffef9 0%,#f7f0dc 100%);border-radius:16px;padding:18px;margin:14px 0;color:#3a2e1f;font-family:'SimSun','宋体',serif;box-shadow:0 8px 24px rgba(139,105,20,.12),inset 0 0 0 1px rgba(201,160,92,.2);position:relative;overflow:hidden;max-width:520px;word-break:break-all}
.cg-card::before{content:'';position:absolute;top:0;left:0;right:0;height:3px;background:linear-gradient(90deg,#8b6914,#c9a05c,#8b6914);opacity:.8}
.cg-top{display:flex;justify-content:space-between;align-items:center;padding-bottom:10px;border-bottom:1px dashed rgba(201,160,92,.35);margin-bottom:12px}
.cg-title{font-size:13px;color:#8b6914;letter-spacing:1px;font-weight:bold}
.cg-time{font-size:13px;color:#8b6914;font-family:'SF Mono','Courier New',monospace}
.cg-place{background:rgba(201,160,92,.1);border:1px solid rgba(201,160,92,.35);border-radius:10px;padding:10px 12px;margin-bottom:12px;font-size:13px;color:#3a2e1f;line-height:1.6;text-align:center;font-weight:bold}
.cg-mid{margin-bottom:10px}
.cg-row{display:flex;gap:10px;padding:10px 0;border-bottom:1px solid rgba(201,160,92,.15);align-items:flex-start}
.cg-row:last-child{border-bottom:none}
.cg-label{min-width:65px;font-size:12px;color:#8b6914;letter-spacing:1px;flex-shrink:0;padding-top:2px;font-weight:bold}
.cg-v{flex:1;font-size:12.5px;color:#3a2e1f;line-height:1.7;font-weight:500}
.cg-private{background:rgba(184,134,11,.06);border:1px solid rgba(184,134,11,.25);border-radius:12px;padding:12px;margin:12px 0}
.cg-private-title{font-size:11px;color:#b8860b;letter-spacing:2px;margin-bottom:8px;font-weight:bold;text-align:center}
.cg-pri.cg-label{color:#b8860b;font-weight:bold}
.cg-pri.cg-v{color:#6b4f0a;font-style:italic}
.cg-aware{background:rgba(201,160,92,.1);border:1px solid rgba(201,160,92,.25);border-radius:10px;padding:10px 12px;margin:10px 0;font-size:12px;color:#8b6914;text-align:center;font-style:italic;font-weight:bold}
.cg-easter{background:rgba(184,134,11,.08);border:1px dashed rgba(184,134,11,.4);border-radius:10px;padding:10px 12px;margin-top:8px;font-size:12px;color:#b8860b;font-style:italic;text-align:center}
